// Some portions generated by Codex
package org.eclipse.rdf4j.sail.nativerdf.wal;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.sail.nativerdf.ValueStore;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreWalReaderReviewRegressionTest {

	private static final int LEXICAL_LENGTH = 2 * 1024 * 1024;

	@TempDir
	Path directory;

	@Test
	void recoversLiteralAcceptedAndForcedByWriter() throws Exception {
		runProbe("large");
	}

	@Test
	void recoversSmallValueAfterUnrelatedLargeLiteral() throws Exception {
		runProbe("following");
	}

	@Test
	void readsLargeCompactLiteralWithoutUtf16Amplification() throws Exception {
		runProbe("compact");
	}

	@Test
	void diskReplayReadsLargeCompactLiteralWithoutUtf16Amplification() throws Exception {
		runProbe("disk-compact");
	}

	@Test
	void restoresLargeCompactLiteralWithoutFullPayloadCopies() throws Exception {
		runProbe("recover-compact");
	}

	@Test
	void restoresReadableLiteralOnSmallHeap() throws Exception {
		runProbe("recover");
	}

	private void runProbe(String mode) throws Exception {
		String classpath = System.getProperty("surefire.test.class.path", System.getProperty("java.class.path"));
		Path output = directory.resolve("reader-review-" + mode + ".log");
		Process process = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				argsForHeap(mode), "-XX:+ExitOnOutOfMemoryError", "-cp", classpath,
				ValueStoreWalReaderReviewRegressionTest.class.getName(), directory.resolve(mode).toString(), mode)
						.redirectErrorStream(true)
						.redirectOutput(output.toFile())
						.start();
		try {
			boolean exited = process.waitFor(60, TimeUnit.SECONDS);
			assertThat(exited).as("Reader regression subprocess must finish").isTrue();
			assertThat(process.exitValue()).withFailMessage("WAL reader regression:%n%s", Files.readString(output))
					.isZero();
		} finally {
			process.destroyForcibly();
		}
	}

	private static String argsForHeap(String mode) {
		if ("recover-compact".equals(mode)) {
			// NativeStore's own indexes remain live during recovery; leave room for them as well as the WAL value.
			return "-Xmx80m";
		}
		return mode.contains("compact") ? "-Xmx64m" : "-Xmx32m";
	}

	public static void main(String[] args) throws Exception {
		ValueStoreWalConfig config = ValueStoreWalConfig.builder()
				.walDirectory(Path.of(args[0]))
				.storeUuid("reader-review-regression")
				.syncPolicy(ValueStoreWalConfig.SyncPolicy.COMMIT)
				.recoverValueStoreOnOpen(true)
				.build();
		int lexicalLength = args[1].contains("compact") ? 24 * 1024 * 1024 : LEXICAL_LENGTH;
		writeDurableValues(config, lexicalLength);
		System.out.println("WRITER_FORCED_BOTH_RECORDS");
		ValueStoreWalSearch search = ValueStoreWalSearch.open(config);
		if (args[1].startsWith("recover")) {
			Path values = Files.createDirectories(Path.of(args[0]).resolve("values"));
			try (ValueStoreWAL wal = ValueStoreWAL.open(config);
					ValueStore store = new ValueStore(values.toFile(), false, 16, 16, 16, 16, wal)) {
				if (!"small-value".equals(store.getValue(2).stringValue())) {
					throw new AssertionError("Automatic recovery must preserve IDs after the large value");
				}
			}
		} else if ("disk-compact".equals(args[1])) {
			try (ValueStoreWalReader reader = ValueStoreWalReader.open(config);
					ValueStoreWalRecovery.DiskReplay replay = new ValueStoreWalRecovery().replayToDisk(reader,
							Path.of(args[0]))) {
				if (!replay.complete() || replay.read(1).lexical().length() != lexicalLength) {
					throw new AssertionError("Temporary recovery dictionary must preserve the large compact value");
				}
			}
		} else if ("large".equals(args[1]) || "compact".equals(args[1])) {
			Value recovered = search.findValueById(1);
			if (!(recovered instanceof Literal literal) || literal.getLabel().length() != lexicalLength) {
				throw new AssertionError("The durably logged literal must remain recoverable");
			}
		} else {
			Value recovered = search.findValueById(2);
			if (recovered == null || !"small-value".equals(recovered.stringValue())) {
				throw new AssertionError("An unrelated larger record must not hide the small value");
			}
		}
		System.out.println("READER_REVIEW_PROBE_PASSED");
	}

	private static void writeDurableValues(ValueStoreWalConfig config, int lexicalLength) throws Exception {
		try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
			wal.logMint(1, ValueStoreWalValueKind.LITERAL, "x".repeat(lexicalLength), "", "", 0);
			long lsn = wal.logMint(2, ValueStoreWalValueKind.BNODE, "small-value", "", "", 0);
			wal.awaitDurable(lsn);
		}
	}
}
